shell_commands:
node -e '
const fs = require("fs");
const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
pkg.version = "0.4.0";
pkg.dependencies = {
  "@types/express": "^5.0.0",
  "@types/node": "^26.5.1",
  "@types/ws": "^8.5.10",
  "ajv": "^6.15.0",
  "cookie": "^2.0.1",
  "cookie-parser": "^1.4.7",
  "cors": "^2.8.5",
  "express": "^5.2.1",
  "uuid": "^14.0.2",
  "ws": "^8.16.0"
};
fs.writeFileSync("package.json", JSON.stringify(pkg, null, 2) + "\n");

const lock = JSON.parse(fs.readFileSync("package-lock.json", "utf8"));
lock.version = "0.4.0";
lock.packages[""].version = "0.4.0";
lock.packages[""].dependencies = {
  "@types/express": "^5.0.0",
  "@types/node": "^26.5.1",
  "@types/ws": "^8.5.10",
  "ajv": "^6.15.0",
  "cookie": "^2.0.1",
  "cookie-parser": "^1.4.7",
  "cors": "^2.8.5",
  "express": "^5.2.1",
  "uuid": "^14.0.2",
  "ws": "^8.16.0"
};
for (const k of ["node_modules/ajv", "node_modules/fast-deep-equal", "node_modules/fast-json-stable-stringify", "node_modules/json-schema-traverse", "node_modules/uri-js", "node_modules/punycode"]) {
  if (lock.packages[k]) delete lock.packages[k].dev;
}
fs.writeFileSync("package-lock.json", JSON.stringify(lock, null, 2) + "\n");
' && git --no-pager diff package.json package-lock.json
